// ---------------------------------------------------------------------------
// DESPAWN + POOL
// A node can be registered in seven places at once. Removing it from six and
// forgetting the seventh leaves a ghost: invisible, still burning CPU, and
// possibly still colliding. Everything below unregisters symmetrically.
// ---------------------------------------------------------------------------
var POOL = {};
