  if (!n) return false;

  // depth first, so a child never outlives its parent
  var kids = (n.children || []).slice();
  for (var k = 0; k < kids.length; k++) despawn(kids[k], { _child: true, pool: opts.pool });

  spliceOut(actors, function (a) { return a === n; });
  spliceOut(POSED, function (p) { return p === n; });
  spliceOut(ANIMS, function (a) { return a === n; });
  spliceOut(ALARMS, function (a) { return a.node === n; });

