  if (typeof PROJECTILES !== "undefined") spliceOut(PROJECTILES, function (p) { return p.owner === n || p.node === n; });
  if (typeof STIMULI !== "undefined") spliceOut(STIMULI, function (s) { return s.node === n || s.from === n; });

