// ---------------------------------------------------------------------------
// v3: BATTLE SYSTEMS  -- GridBattle (Tactics) and ATB (FF7-style), plus the
// menu overlay. Both are modal: while a battle owns the screen, the field
// scene freezes underneath and resumes on resolution.
// ---------------------------------------------------------------------------
// A battle is STARTED by an action:  {action:"startBattle", args:[battleId]}
// scene.battles[battleId] = {
//   type: "grid" | "atb",
//   grid?: { w, h, heights?: [[..]] },        (grid battles)
//   party: [unitId], foes: [unitId],
//   units: { unitId: { name, hp, atk, def, spd, move?, range?, pos?: [x,y] } },
//   rewards?: { xp, gold, items?: [id] },
//   onWin?: [actions], onLose?: [actions]
// }

var BATTLE = null, battleEl = null;

function battleOpen() { return !!BATTLE; }

function startBattle(battleId) {
  var def = (scene.battles || {})[battleId];
  if (!def) return;
  var units = {};
  Object.keys(def.units || {}).forEach(function (id) {
    var u = def.units[id];
    units[id] = {
      id: id, name: u.name || id,
      hp: u.hp || 10, maxHp: u.hp || 10,
      atk: u.atk || 3, def: u.def || 0, spd: u.spd || 5,
      move: u.move || 3, range: u.range || 1,
      pos: (u.pos || [0, 0]).slice(),
      side: (def.party || []).indexOf(id) >= 0 ? "party" : "foe",
      atbBar: 0, acted: false
    };
  });
  BATTLE = {
    id: battleId, def: def, type: def.type || "atb", units: units,
    order: [], turnIdx: 0, phase: "select", selected: null, message: "",
    over: false, rng: srandFor("battle:" + battleId)
  };
  if (BATTLE.type === "grid") {
    BATTLE.order = Object.keys(units).sort(function (a, b) { return units[b].spd - units[a].spd; });
    beginGridTurn();
  }
  renderBattle();
}

function livingUnits(side) {
  return Object.keys(BATTLE.units).filter(function (id) {
    var u = BATTLE.units[id];
    return u.hp > 0 && (!side || u.side === side);
  });
}
function checkBattleEnd() {
  if (livingUnits("foe").length === 0) return endBattle(true);
  if (livingUnits("party").length === 0) return endBattle(false);
  return false;
}
function endBattle(won) {
  BATTLE.over = true;
  var def = BATTLE.def;
  if (won && def.rewards) {
    world.flags.xp = (world.flags.xp || 0) + (def.rewards.xp || 0);
    world.flags.gold = (world.flags.gold || 0) + (def.rewards.gold || 0);
    (def.rewards.items || []).forEach(function (id) { invAdd(id, 1); });
  }
  ((won ? def.onWin : def.onLose) || []).forEach(function (a) { runAction(null, a); });
  BATTLE.message = won ? "Victory!" : "Defeated…";
  renderBattle();
  setTimeout(function () {
    BATTLE = null;
    if (battleEl) battleEl.style.display = "none";
  }, 1600);
  return true;
}

// ---- damage formula: (atk^2 / (atk + def)) with small seeded variance ------
function dmg(att, dfd) {
  var base = Math.max(1, Math.round(att.atk * att.atk / (att.atk + dfd.def)));
  return Math.max(1, base + Math.floor(BATTLE.rng() * 3) - 1);
