// ---------------------------------------------------------------------------
// GRID BATTLE  -- Tactics. Flood-fill movement, Manhattan attack range.
// ---------------------------------------------------------------------------
function gridAt(x, y) {
  var ids = Object.keys(BATTLE.units);
  for (var i = 0; i < ids.length; i++) {
    var u = BATTLE.units[ids[i]];
    if (u.hp > 0 && u.pos[0] === x && u.pos[1] === y) return u;
  }
