}
function floodMove(u) {
  var g = BATTLE.def.grid || { w: 8, h: 8 };
  var seen = {}, out = [], q = [[u.pos[0], u.pos[1], 0]];
  seen[u.pos[0] + "," + u.pos[1]] = true;
  while (q.length) {
    var c = q.shift(), x = c[0], y = c[1], d = c[2];
    out.push([x, y]);
    if (d >= u.move) continue;
    [[1,0],[-1,0],[0,1],[0,-1]].forEach(function (dxy) {
      var nx = x + dxy[0], ny = y + dxy[1], key = nx + "," + ny;
      if (nx < 0 || ny < 0 || nx >= g.w || ny >= g.h || seen[key]) return;
      var occ = gridAt(nx, ny);
      if (occ && occ.side !== u.side) return; // enemies block, allies pass-through
      seen[key] = true;
      q.push([nx, ny, d + 1]);
    });
  }
  return out.filter(function (c) { return !gridAt(c[0], c[1]) || (c[0] === u.pos[0] && c[1] === u.pos[1]); });
}
