  while (tries++ < 64) {
    var id = BATTLE.order[BATTLE.turnIdx % BATTLE.order.length];
    BATTLE.turnIdx++;
    var u = BATTLE.units[id];
    if (u && u.hp > 0) {
      BATTLE.active = id;
      BATTLE.phase = u.side === "party" ? "move" : "ai";
