  var targets = livingUnits("party").map(function (id) { return BATTLE.units[id]; });
  if (!targets.length) return;
  targets.sort(function (a, b) {
    var da = Math.abs(a.pos[0]-u.pos[0]) + Math.abs(a.pos[1]-u.pos[1]);
    var db = Math.abs(b.pos[0]-u.pos[0]) + Math.abs(b.pos[1]-u.pos[1]);
