// ---------------------------------------------------------------------------
// ATB BATTLE  -- FF7-style. Bars fill by spd; full bar = menu turn.
// ---------------------------------------------------------------------------
function updateAtb(dt) {
  if (!BATTLE || BATTLE.type !== "atb" || BATTLE.over) return;
  if (BATTLE.phase === "menu" || BATTLE.phase === "target") return; // pause while choosing
  Object.keys(BATTLE.units).forEach(function (id) {
    var u = BATTLE.units[id];
    if (u.hp <= 0) return;
    u.atbBar += u.spd * dt * 12;
    if (u.atbBar >= 100) {
      u.atbBar = 100;
      if (u.side === "party" && BATTLE.phase === "select") {
        BATTLE.active = id;
        BATTLE.phase = "menu";
