  if (!targets.length) return;
  var t = BATTLE.units[targets[Math.floor(BATTLE.rng() * targets.length)]];
  var d = dmg(u, t);
  t.hp = Math.max(0, t.hp - d);
  u.atbBar = 0;
  BATTLE.message = u.name + " strikes " + t.name + " for " + d;
  checkBattleEnd();
