    var t = BATTLE.units[targetId];
    if (!t) return;
    var d = dmg(u, t);
    t.hp = Math.max(0, t.hp - d);
    BATTLE.message = u.name + " attacks " + t.name + " for " + d;
  } else if (action === "item") {
    var it = itemDef(targetId);
    if (invCount(targetId) > 0 && it.heal) {
      invRemove(targetId, 1);
      u.hp = Math.min(u.maxHp, u.hp + it.heal);
      BATTLE.message = u.name + " uses " + (it.name || targetId) + " (+" + it.heal + ")";
    }
