// ---------------------------------------------------------------------------
// BATTLE UI  -- DOM overlay, same pattern as dialogue/shop.
// ---------------------------------------------------------------------------
function renderBattle() {
  if (!BATTLE) return;
  if (!battleEl) {
    battleEl = document.createElement("div");
    battleEl.style.cssText = "position:absolute;inset:8px;background:rgba(10,14,20,.96);" +
